#pragma once
#include "Prelude.h"
#include "IntegerDivision.h"
#include "ModularArithmetic.h"

namespace finals_math {
// Requires nonnegative a,b. Returns g,x,y with a*x+b*y=g.
inline tuple<i64, i128, i128> extended_gcd(i64 a, i64 b) {
	if (a < 0 || b < 0)
		throw invalid_argument("nonnegative gcd inputs");
	i128 r = a, s = b, x = 1, y = 0, u = 0, v = 1;
	while (s) {
		i128 q = r / s;
		i128 t = r - q * s;
		r = s;
		s = t;
		t = x - q * u;
		x = u;
		u = t;
		t = y - q * v;
		y = v;
		v = t;
	}
	return {i64(r), x, y};
}
inline optional<i64> inverse(i64 a, i64 m) {
	if (m <= 1)
		throw invalid_argument("inverse modulus must exceed one");
	auto [g, x, y] = extended_gcd(norm(a, m), m);
	(void)y;
	if (g != 1) return nullopt;
	return i64((x % m + m) % m);
}
struct Congruence {
	i64 residue, modulus;
};
// Merge x=a (mod m), x=b (mod n); nullopt = incompatible.
// Positive moduli. Throws if the merged lcm exceeds LLONG_MAX.
inline optional<Congruence> crt(Congruence a, Congruence b) {
	a.residue = norm(a.residue, a.modulus);
	b.residue = norm(b.residue, b.modulus);
	auto [g, x, y] = extended_gcd(a.modulus, b.modulus);
	(void)y;
	i128 delta = i128(b.residue) - a.residue;
	if (delta % g) return nullopt;
	i64 n = b.modulus / g;
	i128 t = (delta / g * x) % n;
	if (t < 0) t += n;
	i64 lcm = narrow(i128(a.modulus) * n);
	i128 r = (i128(a.residue) + i128(a.modulus) * t) % lcm;
	return Congruence{i64(r), lcm};
}
} // namespace finals_math
